    29  import INPUT_IDS from '@src/types/form/WorkspaceReportFieldForm';
    30  import InitialListValueSelector from './InitialListValueSelector';
    31  import TypeSelector from './TypeSelector';
    32
    33  type CreateReportFieldsPageProps = WithPolicyAndFullscreenLoadingProps & StackScreenProps<SettingsNavigatorParamList, typeof SCREENS.WORKSPACE.REPORT_FIELDS_CREATE>;
    34
    35  const defaultDate = DateUtils.extractDate(new Date().toString());
    36
    37  function CreateReportFieldsPage({
    38      policy,
    39      route: {
    40          params: {policyID},
    41      },
    42  }: CreateReportFieldsPageProps) {
    43      const styles = useThemeStyles();
    44      const {translate} = useLocalize();
    45      const formRef = useRef<FormRef>(null);
    46      const [formDraft] = useOnyx(ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM_DRAFT);
    47
    48      const availableListValuesLength = (formDraft?.[INPUT_IDS.DISABLED_LIST_VALUES] ?? []).filter((disabledListValue) => !disabledListValue).length;
    49
    50      const submitForm = useCallback(
    51          (values: FormOnyxValues<typeof ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM>) => {
    52              ReportField.createReportField(policyID, {
    53                  name: values[INPUT_IDS.NAME],
    54                  type: values[INPUT_IDS.TYPE],
    55                  initialValue: values[INPUT_IDS.INITIAL_VALUE],
    56              });
    57              Navigation.goBack();
    58          },
    59          [policyID],
    60      );
    61
    62      const validateForm = useCallback(
    63          (values: FormOnyxValues<typeof ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM>): FormInputErrors<typeof ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM> => {
    64              const {name, type} = values;
    65              const errors: FormInputErrors<typeof ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM> = {};
    66
    67              if (!ValidationUtils.isRequiredFulfilled(name)) {
    68                  errors[INPUT_IDS.NAME] = translate('workspace.reportFields.reportFieldNameRequiredError');
    69              } else if (Object.values(policy?.fieldList ?? {}).some((reportField) => reportField.name === name)) {
    70                  errors[INPUT_IDS.NAME] = translate('workspace.reportFields.existingReportFieldNameError');
    71              } else if ([...name].length > CONST.WORKSPACE_REPORT_FIELD_POLICY_MAX_LENGTH) {
    72                  // Uses the spread syntax to count the number of Unicode code points instead of the number of UTF-16 code units.
    73                  ErrorUtils.addErrorMessage(
    74                      errors,
    75                      INPUT_IDS.NAME,
    76                      translate('common.error.characterLimitExceedCounter', {length: [...name].length, limit: CONST.WORKSPACE_REPORT_FIELD_POLICY_MAX_LENGTH}),
    77                  );
    78              }
    79
    80              if (!ValidationUtils.isRequiredFulfilled(type)) {
    81                  errors[INPUT_IDS.TYPE] = translate('workspace.reportFields.reportFieldTypeRequiredError');
    82              }
    83
    84              return errors;
    85          },
    86          [policy?.fieldList, translate],
    87      );
    88
    89      useEffect(() => {
    90          ReportField.setInitialCreateReportFieldsForm();
    91      }, []);
    92
    93      const [modal] = useOnyx(ONYXKEYS.MODAL);
    94
    95      return (
    96          <AccessOrNotFoundWrapper
    97              accessVariants={[CONST.POLICY.ACCESS_VARIANTS.ADMIN, CONST.POLICY.ACCESS_VARIANTS.PAID]}
    98              policyID={policyID}
    99              featureName={CONST.POLICY.MORE_FEATURES.ARE_REPORT_FIELDS_ENABLED}
   100              shouldBeBlocked={PolicyUtils.hasAccountingConnections(policy)}
   101          >
   102              <ScreenWrapper
   103                  includeSafeAreaPaddingBottom={false}
   104                  style={styles.defaultModalContainer}
   105                  testID={CreateReportFieldsPage.displayName}
   106                  shouldEnableMaxHeight
   107              >
   108                  <HeaderWithBackButton
   109                      title={translate('workspace.reportFields.addField')}
   110                      onBackButtonPress={Navigation.goBack}
   111                  />
   112                  <FormProvider
   113                      ref={formRef}
   114                      style={[styles.mh5, styles.flex1]}
   115                      formID={ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM}
   116                      onSubmit={submitForm}
   117                      validate={validateForm}
   118                      submitButtonText={translate('common.save')}
   119                      enabledWhenOffline
   120                      shouldValidateOnBlur={false}
   121                      disablePressOnEnter={!!modal?.isVisible}
   122                  >
   123                      {({inputValues}) => (
   124                          <View style={styles.mhn5}>
   125                              <InputWrapper
   126                                  InputComponent={TextPicker}
   127                                  inputID={INPUT_IDS.NAME}
   128                                  label={translate('common.name')}
   129                                  subtitle={translate('workspace.reportFields.nameInputSubtitle')}
   130                                  description={translate('common.name')}
   131                                  rightLabel={translate('common.required')}
   132                                  accessibilityLabel={translate('workspace.editor.nameInputLabel')}
   133                                  maxLength={CONST.WORKSPACE_REPORT_FIELD_POLICY_MAX_LENGTH}
   134                                  multiline={false}
   135                                  role={CONST.ROLE.PRESENTATION}
   136                              />
   137                              <InputWrapper
   138                                  InputComponent={TypeSelector}
   139                                  inputID={INPUT_IDS.TYPE}
   140                                  label={translate('common.type')}
   141                                  subtitle={translate('workspace.reportFields.typeInputSubtitle')}
   142                                  rightLabel={translate('common.required')}
   143                                  onTypeSelected={(type) => formRef.current?.resetForm({...inputValues, type, initialValue: type === CONST.REPORT_FIELD_TYPES.DATE ? defaultDate : ''})}
   144                              />
   145
   146                              {inputValues[INPUT_IDS.TYPE] === CONST.REPORT_FIELD_TYPES.TEXT && (
   147                                  <InputWrapper
   148                                      InputComponent={TextPicker}
   149                                      inputID={INPUT_IDS.INITIAL_VALUE}
   150                                      label={translate('common.initialValue')}
   151                                      subtitle={translate('workspace.reportFields.initialValueInputSubtitle')}
   152                                      description={translate('common.initialValue')}
   153                                      accessibilityLabel={translate('workspace.editor.initialValueInputLabel')}
   154                                      maxLength={CONST.WORKSPACE_REPORT_FIELD_POLICY_MAX_LENGTH}
   155                                      multiline={false}
   156                                      role={CONST.ROLE.PRESENTATION}
   157                                  />
   158                              )}
   159
   160                              {inputValues[INPUT_IDS.TYPE] === CONST.REPORT_FIELD_TYPES.DATE && (
   161                                  <MenuItemWithTopDescription
   162                                      title={translate('common.currentDate')}
   163                                      description={translate('common.date')}
   164                                      rightLabel={translate('common.required')}
   165                                      interactive={false}
   166                                  />
   167                              )}
   168
   169                              {inputValues[INPUT_IDS.TYPE] === CONST.REPORT_FIELD_TYPES.LIST && availableListValuesLength > 0 && (
   170                                  <InputWrapper
   171                                      InputComponent={InitialListValueSelector}
   172                                      inputID={INPUT_IDS.INITIAL_VALUE}
   173                                      label={translate('common.initialValue')}
   174                                      subtitle={translate('workspace.reportFields.listValuesInputSubtitle')}
   175                                      rightLabel={translate('common.required')}
   176                                  />
   177                              )}
   178
   179                              {inputValues[INPUT_IDS.TYPE] === CONST.REPORT_FIELD_TYPES.LIST && (
   180                                  <MenuItemWithTopDescription
   181                                      description={translate('workspace.reportFields.listValues')}
   182                                      shouldShowRightIcon
   183                                      onPress={() => Navigation.navigate(ROUTES.WORKSPACE_REPORT_FIELDS_LIST_VALUES.getRoute(policyID))}
   184                                  />
   185                              )}
   186
   187                              {inputValues[INPUT_IDS.TYPE] === CONST.REPORT_FIELD_TYPES.LIST && (
   188                                  <MenuItemWithTopDescription
   189                                      description={translate('workspace.reportFields.listValues')}
   190                                      shouldShowRightIcon
   191                                      onPress={() => Navigation.navigate(ROUTES.WORKSPACE_REPORT_FIELDS_LIST_VALUES.getRoute(policyID))}
   192                                  />
   193                              )}
   194                          </View>
   195                      )}
   196                  </FormProvider>
   197              </ScreenWrapper>
   198          </AccessOrNotFoundWrapper>
   199      );
   200  }
   201
   202  CreateReportFieldsPage.displayName = 'CreateReportFieldsPage';
   203
   204  export default withPolicyAndFullscreenLoading(CreateReportFieldsPage);
