    27
    28  type ReportFieldsSettingsPageProps = WithPolicyAndFullscreenLoadingProps & StackScreenProps<SettingsNavigatorParamList, typeof SCREENS.WORKSPACE.REPORT_FIELDS_SETTINGS>;
    29
    30  function ReportFieldsSettingsPage({
    31      policy,
    32      route: {
    33          params: {policyID, reportFieldID},
    34      },
    35  }: ReportFieldsSettingsPageProps) {
    36      const styles = useThemeStyles();
    37      const {translate} = useLocalize();
    38      const [isDeleteModalVisible, setIsDeleteModalVisible] = useState(false);
    39
    40      const hasAccountingConnections = PolicyUtils.hasAccountingConnections(policy);
    41      const reportFieldKey = ReportUtils.getReportFieldKey(reportFieldID);
    42      const reportField = policy?.fieldList?.[reportFieldKey] ?? null;
    43
    44      if (!reportField) {
    45          return <NotFoundPage />;
    46      }
    47
    48      const isDateFieldType = reportField.type === CONST.REPORT_FIELD_TYPES.DATE;
    49      const isListFieldType = reportField.type === CONST.REPORT_FIELD_TYPES.LIST;
    50      const isListFieldEmpty = isListFieldType && reportField.values.length <= 0;
    51
    52      const deleteReportFieldAndHideModal = () => {
    53          ReportField.deleteReportFields(policyID, [reportFieldKey]);
    54          setIsDeleteModalVisible(false);
    55          Navigation.goBack();
    56      };
    57
    58      return (
    59          <AccessOrNotFoundWrapper
    60              accessVariants={[CONST.POLICY.ACCESS_VARIANTS.ADMIN, CONST.POLICY.ACCESS_VARIANTS.PAID]}
    61              policyID={policyID}
    62              featureName={CONST.POLICY.MORE_FEATURES.ARE_REPORT_FIELDS_ENABLED}
    63          >
    64              <ScreenWrapper
    65                  includeSafeAreaPaddingBottom={false}
    66                  style={[styles.defaultModalContainer]}
    67                  testID={ReportFieldsSettingsPage.displayName}
    68              >
    69                  <HeaderWithBackButton
    70                      title={reportField.name}
    71                      shouldSetModalVisibility={false}
    72                  />
    73                  <ConfirmModal
    74                      title={translate('workspace.reportFields.delete')}
    75                      isVisible={isDeleteModalVisible && !hasAccountingConnections}
    76                      onConfirm={deleteReportFieldAndHideModal}
    77                      onCancel={() => setIsDeleteModalVisible(false)}
    78                      shouldSetModalVisibility={false}
    79                      prompt={translate('workspace.reportFields.deleteConfirmation')}
    80                      confirmText={translate('common.delete')}
    81                      cancelText={translate('common.cancel')}
    82                      danger
    83                  />
    84                  <View style={styles.flexGrow1}>
    85                      <MenuItemWithTopDescription
    86                          style={[styles.moneyRequestMenuItem]}
    87                          titleStyle={styles.flex1}
    88                          title={reportField.name}
    89                          description={translate('common.name')}
    90                          interactive={false}
    91                      />
    92                      <MenuItemWithTopDescription
    93                          style={[styles.moneyRequestMenuItem]}
    94                          titleStyle={styles.flex1}
    95                          title={Str.recapitalize(translate(WorkspaceReportFieldUtils.getReportFieldTypeTranslationKey(reportField.type)))}
    96                          description={translate('common.type')}
    97                          interactive={false}
    98                      />
    99                      {!isListFieldEmpty && (
   100                          <MenuItemWithTopDescription
   101                              style={[styles.moneyRequestMenuItem]}
   102                              titleStyle={styles.flex1}
   103                              title={WorkspaceReportFieldUtils.getReportFieldInitialValue(reportField)}
   104                              description={translate('common.initialValue')}
   105                              shouldShowRightIcon={!isDateFieldType && !hasAccountingConnections}
   106                              interactive={!isDateFieldType && !hasAccountingConnections}
   107                              onPress={() => Navigation.navigate(ROUTES.WORKSPACE_EDIT_REPORT_FIELDS_INITIAL_VALUE.getRoute(policyID, reportFieldID))}
   108                          />
   109                      )}
   110                      {isListFieldType && (
   111                          <MenuItemWithTopDescription
   112                              style={[styles.moneyRequestMenuItem]}
   113                              titleStyle={styles.flex1}
   114                              description={translate('workspace.reportFields.listValues')}
   115                              shouldShowRightIcon
   116                              onPress={() => Navigation.navigate(ROUTES.WORKSPACE_REPORT_FIELDS_LIST_VALUES.getRoute(policyID, reportFieldID))}
   117                          />
   118                      )}
   119                      {!hasAccountingConnections && (
   120                          <View style={styles.flexGrow1}>
   121                              <MenuItem
   122                                  icon={Expensicons.Trashcan}
   123                                  title={translate('common.delete')}
   124                                  onPress={() => setIsDeleteModalVisible(true)}
   125                              />
   126                          </View>
   127                      )}
   128                  </View>
   129              </ScreenWrapper>
   130          </AccessOrNotFoundWrapper>
   131      );
   132  }
