     4  import useLocalize from '@hooks/useLocalize';
     5  import * as WorkspaceReportFieldUtils from '@libs/WorkspaceReportFieldUtils';
     6  import CONST from '@src/CONST';
     7  import type {PolicyReportFieldType} from '@src/types/onyx/Policy';
     8
     9  type ReportFieldItemType = {
    10      /** The value */
    11      value: PolicyReportFieldType;
    12
    13      /** The display text */
    14      text: string;
    15
    16      /** The key for list */
    17      keyForList: string;
    18
    19      /** Whether the value is selected */
    20      isSelected: boolean;
    21  };
    22
    23  type ReportFieldTypePickerProps = {
    24      /** Currently selected report field type */
    25      defaultValue: PolicyReportFieldType;
    26
    27      /** Function to call when the user selects a report field type */
    28      onOptionSelected: (reportField: ReportFieldItemType) => void;
    29  };
    30
    31  function ReportFieldTypePicker({defaultValue, onOptionSelected}: ReportFieldTypePickerProps) {
    32      const {translate} = useLocalize();
    33
    34      const typeSections = useMemo(() => {
    35          const data = Object.values(CONST.REPORT_FIELD_TYPES).map((reportFieldType) => ({
    36              keyForList: reportFieldType,
    37              value: reportFieldType,
    38              isSelected: defaultValue === reportFieldType,
    39              text: translate(WorkspaceReportFieldUtils.getReportFieldTypeTranslationKey(reportFieldType)),
    40              alternateText: translate(WorkspaceReportFieldUtils.getReportFieldAlternativeTextTranslationKey(reportFieldType)),
    41          }));
    42
    43          return [{data}];
    44      }, [defaultValue, translate]);
    45
    46      return (
    47          <SelectionList
    48              sections={typeSections}
    49              ListItem={RadioListItem}
    50              onSelectRow={onOptionSelected}
    51              initiallyFocusedOptionKey={typeSections[0].data.find((reportField) => reportField.isSelected)?.keyForList}
    52          />
    53      );
    54  }
    55
    56  ReportFieldTypePicker.displayName = 'ReportFieldTypePicker';
    57
    58  export default ReportFieldTypePicker;
    59
    60  export type {ReportFieldItemType};
