    10  import CONST from '@src/CONST';
    11  import type {PolicyReportFieldType} from '@src/types/onyx/Policy';
    12  import TypeSelectorModal from './TypeSelectorModal';
    13
    14  type TypeSelectorProps = Pick<MenuItemBaseProps, 'label' | 'rightLabel' | 'errorText'> & {
    15      /** Currently selected type */
    16      value?: string;
    17
    18      /** Subtitle to display on field */
    19      subtitle?: string;
    20
    21      /** Function to call when the user selects a type */
    22      onInputChange?: (value: string) => void;
    23
    24      /** Function to call when the user selects a type */
    25      onTypeSelected?: (reportFieldType: PolicyReportFieldType) => void;
    26  };
    27
    28  function TypeSelector({value, label = '', rightLabel, subtitle = '', errorText = '', onInputChange, onTypeSelected}: TypeSelectorProps, forwardedRef: ForwardedRef<View>) {
    29      const {translate} = useLocalize();
    30
    31      const [isPickerVisible, setIsPickerVisible] = useState(false);
    32
    33      const showPickerModal = () => {
    34          setIsPickerVisible(true);
    35      };
    36
    37      const hidePickerModal = () => {
    38          setIsPickerVisible(false);
    39      };
    40
    41      const updateTypeInput = (reportField: ReportFieldItemType) => {
    42          onInputChange?.(reportField.value);
    43          onTypeSelected?.(reportField.value);
    44          hidePickerModal();
    45      };
    46
    47      return (
    48          <View>
    49              <MenuItemWithTopDescription
    50                  ref={forwardedRef}
    51                  shouldShowRightIcon
    52                  title={value ? Str.recapitalize(translate(WorkspaceReportFieldUtils.getReportFieldTypeTranslationKey(value as PolicyReportFieldType))) : ''}
    53                  description={label}
    54                  rightLabel={rightLabel}
    55                  brickRoadIndicator={errorText ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR : undefined}
    56                  errorText={errorText}
    57                  onPress={showPickerModal}
    58              />
    59              <TypeSelectorModal
    60                  isVisible={isPickerVisible}
    61                  currentType={value as PolicyReportFieldType}
    62                  onClose={hidePickerModal}
    63                  onTypeSelected={updateTypeInput}
    64                  label={label}
    65                  subtitle={subtitle}
    66              />
    67          </View>
    68      );
    69  }
    70
    71  TypeSelector.displayName = 'TypeSelector';
    72
    73  export default forwardRef(TypeSelector);

